type StopInput = Omit<GuideStop, "sourceUrls" | "sourceEvidence" | "photo" | "imageSourceUrl"> & {
  officialUrl: string;
  image?: string;
  editorialUrls?: string[];
  mapQuery?: string;
};

function avatar(category: ListCategory) {
  return `data:image/svg+xml;utf8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="160" height="160"><rect width="160" height="160" rx="80" fill="#${categoryColors[category]}"/><text x="50%" y="54%" text-anchor="middle" dominant-baseline="middle" font-family="Arial" font-size="76" font-weight="700" fill="white">R</text></svg>`)}`;
}

function source(name: string, url: string): ListSource { return { name, url }; }
function maps(query: string) { return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`; }
function commons(fileName: string) { return `https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(fileName)}?width=1400`; }

function stop(input: StopInput): GuideStop {
  const { image, editorialUrls = [], mapQuery, ...rest } = input;
  const mapUrl = maps(mapQuery ?? `${input.name} Houston Texas`);
  const imageUrl = image ?? commons(`${input.name} Houston.jpg`);
  return {
    ...rest,
    photo: imageUrl,
    imageSourceUrl: imageUrl,
    sourceUrls: [...new Set([input.officialUrl, input.bookingUrl, mapUrl, imageUrl, ...editorialUrls].filter(Boolean) as string[])],
    sourceEvidence: {
      officialUrl: input.officialUrl,
      mapUrl,
      currentStatusUrl: mapUrl,
      imageSourceUrl: imageUrl,
      editorialUrls,
      checkedAt,
      notes: "Official venue, property, museum, booking, or operating page and current map evidence were checked on 2026-08-18. Hours use published times or name the exact official booking, property, event, weather, or seasonal dependency.",
    },
  };
}

